<?php
declare(strict_types=1);
require dirname(__DIR__).'/photo-desk/app.php';
use function PhotoDesk\{connect,schema,save,record,source_url};
$dir=sys_get_temp_dir().'/desk-test-'.bin2hex(random_bytes(6));mkdir($dir,0700);$db=connect($dir);schema($db);
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function rejects(callable $fn):void{try{$fn();}catch(RuntimeException $e){return;}throw new RuntimeException('Expected rejection');}
$id=save($db,null,0,['title'=>'Фото','company'=>'Компания','request_note'=>'Нужен исходник','source_url'=>'https://example.org/image'],'admin','owner');
check($id===1,'Stable ID');$row=record($db,$id);
save($db,$id,1,['ready'=>1],'photographer','owner');$row=record($db,$id);check($row['ready']===1 && $row['closed']===0,'Photographer does not close');
rejects(fn()=>save($db,$id,2,['closed'=>1],'photographer','owner'));
rejects(fn()=>save($db,$id,1,['response_note'=>'stale'],'admin','owner'));
save($db,$id,2,['closed'=>1],'lawyer','lawyer');$row=record($db,$id);check($row['closed']===1,'Lawyer closes');
save($db,$id,3,['ready'=>0],'photographer','owner');check(record($db,$id)['closed']===1,'Closure independent');
rejects(fn()=>save($db,$id,4,['ready'=>1],'lawyer','lawyer'));
save($db,$id,4,['closed'=>0],'lawyer','lawyer');check(record($db,$id)['closed']===0,'Reopen');
rejects(fn()=>source_url('javascript:alert(1)'));rejects(fn()=>source_url('https://user:pass@example.org'));rejects(fn()=>save($db,null,0,['title'=>'x'],'photographer','owner'));
save($db,$id,5,['response_note'=>'Ответ'],'photographer','owner',[['side'=>'response','name'=>'test.txt','mime'=>'text/plain','size'=>5,'storage_key'=>'test']]);
rejects(fn()=>save($db,$id,6,[],'lawyer','lawyer',[],1));check((int)$db->query('SELECT count(*) FROM attachments')->fetchColumn()===1,'Foreign side attachment preserved');
check(record($db,$id)['revision']===6,'Failed operation rolls back revision');
check(PhotoDesk\resolve_url('https://example.org/a/b','../photo.jpg')==='https://example.org/photo.jpg','Relative redirect resolution');
$meta=PhotoDesk\preview_metadata('<title>Photo</title><meta name="twitter:image" content="/photo.jpg">','https://example.org/a');
check($meta['image']==='https://example.org/photo.jpg' && $meta['title']==='Photo','Twitter image fallback');
rejects(fn()=>PhotoDesk\public_fetch('https://127.0.0.1/private',100));
rejects(fn()=>PhotoDesk\public_fetch('http://example.org',100));
rejects(fn()=>PhotoDesk\public_fetch('https://user:pass@example.org',100));
$katya=save($db,null,0,['title'=>'От Кати','created_by'=>'valera'],'lawyer','katya');
check(record($db,$katya)['created_by']==='katya','Authenticated creator overrides forged form author');
check(PhotoDesk\request_author(record($db,$katya))['title']==='Запрос Кати','Katya heading');
check(PhotoDesk\request_author(['created_by'=>'Katja'])===PhotoDesk\request_author(['created_by'=>'katya']),'Actual Katja login gets Katya blue badge and heading');
save($db,$katya,1,['request_note'=>'Поправил Валера','created_by'=>'valera'],'lawyer','valera');
save($db,$katya,2,['response_note'=>'Отвечает фотограф'],'photographer','photo');
check(record($db,$katya)['created_by']==='katya','Other editors cannot become the creator');
check(str_contains(PhotoDesk\request_author_badge(record($db,$katya)),'requester-katya'),'Katya identity badge');
$valera=save($db,null,0,['title'=>'От Валеры'],'lawyer','valera');check(PhotoDesk\request_author(record($db,$valera))['title']==='Запрос Валеры','Valera heading');
check(PhotoDesk\request_author_badge(['created_by'=>''])==='','Unknown legacy creator has no guessed badge');
check(!str_contains(PhotoDesk\request_author_badge(['created_by'=>'<script>']),'title="Запрос · <script>'),'Fallback login escaped');
$legacy=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$legacy->exec("CREATE TABLE cases(id INTEGER PRIMARY KEY,title TEXT,ready INTEGER,closed INTEGER,revision INTEGER); INSERT INTO cases VALUES(1,'Не менять',1,0,7),(2,'Без истории',0,1,4); CREATE TABLE events(id INTEGER PRIMARY KEY,case_id INTEGER,actor TEXT,action TEXT,created_at TEXT); INSERT INTO events VALUES(1,1,'katya','Запрос создан','then'),(2,1,'valera','Позиция сохранена','later')");
schema($legacy);schema($legacy);
check(record($legacy,1)['created_by']==='katya'&&record($legacy,1)['revision']===7&&record($legacy,1)['ready']===1,'Idempotent migration recovers creator without changing case');
check(record($legacy,2)['created_by']===''&&(int)$legacy->query('SELECT count(*) FROM events')->fetchColumn()===2,'Missing creator stays unknown and audit trail is preserved');
$legacy=null;
rejects(fn()=>PhotoDesk\delete_case($db,$id,6,'photographer','photo','удалить'));
rejects(fn()=>PhotoDesk\delete_case($db,$id,6,'lawyer','katya','нет'));
rejects(fn()=>PhotoDesk\delete_case($db,$id,5,'lawyer','katya','удалить'));
check(record($db,$id)['revision']===6,'Rejected deletion changes nothing');
PhotoDesk\delete_case($db,$id,6,'lawyer','katya','УДАЛИТЬ');
rejects(fn()=>record($db,$id));rejects(fn()=>save($db,$id,7,['response_note'=>'Не вернуть случайно'],'photographer','photo'));
check((int)$db->query('SELECT count(*) FROM attachments')->fetchColumn()===1,'Deleted case keeps original associations for recovery');
check($db->query("SELECT actor FROM events WHERE action='Запрос удалён'")->fetchColumn()==='katya','Deletion audited');
check((int)$db->query('SELECT count(*) FROM cases WHERE deleted_at IS NULL')->fetchColumn()===2,'Other lawyers cases preserved');
$db=null;unlink($dir.'/desk.sqlite');rmdir($dir);echo "Photo desk domain checks passed\n";
